style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
:root {
    -rbx-image-uri: url("https://i.imgur.com/pq9ILs4.jpeg");
    -rbx-image-width: 420px;
    -rbx-image-height: 300px;
    -rbx-image-right: 18px;
    -rbx-image-top: 72px;
    -rbx-image-opacity: 0.98;
    -rbx-image-shadow: 0 8px 30px rgba(0, 0, 0, 0.6);
    -rbx-image-border-radius: 10px;
    -rbx-image-z: 99999;
  }

  .stylish-rbx-image-panel {
    position: fixed;
    top: var(-rbx-image-top);
    right: var(-rbx-image-right);
    width: var(-rbx-image-width);
    height: var(-rbx-image-height);
    background-image: var(-rbx-image-uri);
    background-size: cover;
    background-position: center center;
    background-repeat: no-repeat;
    box-shadow: var(-rbx-image-shadow);
    border-radius: var(-rbx-image-border-radius);
    opacity: var(-rbx-image-opacity);
    z-index: var(-rbx-image-z);
    pointer-events: none;
  }

  header, .site-header, #header, .rbx-navbar {
    background-image: linear-gradient(rgba(0,0,0,0.35), rgba(0,0,0,0.35)), var(-rbx-image-uri) !important;
    background-size: 140px auto !important;
    background-position: right center !important;
    background-repeat: no-repeat !important;
  }

  @media (max-width: 900px) {
    .stylish-rbx-image-panel { display: none; }
  }
}
